function inspector(){return `<aside class="inspector"><span class="hero-eyebrow">プロトタイプ v2 / 2026.09.15</span><h1>タメルコ<br><span>現行デザイン × 新機能</span></h1><p>現状アプリの見た目を維持しつつ、<br>案件詳細・マイ案件・アンケート連鎖を統合。<br>数値・条件は poikatsu-spec を優先。</p><nav aria-label="画面一覧">${[['onboarding/1','user','会員登録・オンボーディング'],['account/profile','settings','アカウント情報'],['home','home','ホーム（TOP）'],['feature/autumn-trip','ticket','特集ページ（ディープリンク）'],['missions','list','今日できること'],['offers','pouch','お得・おすすめ'],['high','chart','お得・高還元'],['quick','clock','お得・すぐできる'],['surveys','spark','簡単（アンケート）'],['invite','gift','友達招待（マイページ内）'],['mycases','bag','マイ案件（マイページ内）'],['offer/travel','bag','通常案件・詳細'],['offer/game','chart','SUR 案件（段階報酬）'],['challenges','spark','チャレンジボーナス'],['surveys','survey','アンケート一覧'],['mypage','user','マイページ']].map(([to,ico,title])=>link(`${icon(ico)}${title}${icon('arrow')}`,to,location.hash===`#${to}`||!location.hash&&to==='home'?'current':'')).join('')}</nav><div class="scope-note"><b>spec に合わせた項目</b><ul><li>合算ポイント／準備中／交換可能</li><li>付与予定 → 自動判定／有人審査で確定</li><li>ミッションは対象活動の完了で自動的に済み</li><li>歩数は 1 回 1 マイルストーン・動画あり／なし</li><li>動画は配信可否で表示、再生済み・本日分終了</li><li>ポイントゲット／挑戦中・判定中・承認・否認</li><li>最低交換 100pt・交換単位 100pt</li><li>アンケートは還元率で換算</li></ul><b>仮値（spec は運用設定）</b><ul><li>歩数 1,000 歩 × 4 回、動画 3 回</li><li>各ポイント額、還元率</li></ul></div><a href="docs/08-spec-gap.md" target="_blank">差分整理ドキュメント ↗</a><span class="inspector-bottom">架空のデータを使用しています。<br>金銭の授受・外部サービスへの接続はありません。</span></aside>`;}
function demoPanel(){const LM=L(state);return `<aside class="demo-panel"><div class="demo-title">${icon('settings')}<h2>表示・動作の確認</h2></div><p>ここはモックの検証用です。<br>アプリの画面には含みません。</p><fieldset class="mini-games-demo-mode"><legend>遊ぶタブの表示</legend>${[['tier1','Tier1：サイコロのみ'],['all','全体版：全ミニゲーム']].map(([mode,label])=>button(label,'mini-games-mode','btn secondary wide small',`data-value="${mode}" aria-pressed="${miniGamesMode(state)===mode}"`)).join('')}</fieldset>${button('デイリーミッションを未完了に戻す','reset-daily-missions','btn secondary wide small')}${button('デイリーミッションを5件で確認','demo-five-missions','btn secondary wide small')}${accountUI.demo()}${dialogDemoPanel()}<label>画面の表示状態<select id="demo-view">${[['normal','通常'],['loading','読み込み中'],['error','取得エラー'],['empty','0件'],['ended','案件未発見（掲載終了）']].map(([v,n])=>`<option value="${v}" ${viewState===v?'selected':''}>${n}</option>`).join('')}</select></label><label>アンケートの状態<select id="demo-survey-preview">${[['normal','通常'],['empty','回答可能な案件なし'],['url-error','回答URL不備'],['interrupted','中断（付与なし）'],['ended','募集終了（付与なし）']].map(([v,n])=>`<option value="${v}" ${(state.surveyPreview||'normal')===v?'selected':''}>${n}</option>`).join('')}</select></label><label>確認する日付<input type="date" id="demo-date" value="${state.date}"></label><label>利用者の状態<select id="demo-persona">${[['regular','継続利用者（成人）'],['new','新規利用者（インストール案件 未解禁）'],['minor','未成年（広告配信なし）'],['guest','ゲスト（会員登録前）'],['card','クレカ案件を利用済み']].map(([v,n])=>`<option value="${v}" ${state.persona===v?'selected':''}>${n}</option>`).join('')}</select></label><label>端末の OS（案件の絞り込み）<select id="demo-os">${[['ios','iOS'],['android','Android']].map(([v,n])=>`<option value="${v}" ${(state.os||'ios')===v?'selected':''}>${n}</option>`).join('')}</select></label><label>iOSトラッキング（モック用）<select id="demo-tracking">${[['notDetermined','未許可（初回）'],['authorized','許可済み'],['denied','拒否済み'],['restricted','制限あり']].map(([v,n])=>`<option value="${v}" ${(state.trackingPermission||'notDetermined')===v?'selected':''}>${n}</option>`).join('')}</select></label><p class="tiny">端末の実際の許可状態は変更しません。</p><label>歩数計測の連携<select id="demo-steplink">${[['linked','連携済み'],['unlinked','未許諾'],['denied','許可しない／拒否済み'],['unavailable','利用不可（計測できない端末）']].map(([v,n])=>`<option value="${v}" ${state.stepLink===v?'selected':''}>${n}</option>`).join('')}</select></label><label>読み込み・交換の状態<select id="demo-scenario">${[['normal','通常'],['empty','アンケートの配信なし'],['error','読み込み・送信エラー'],['cap','日次交換総額上限に到達']].map(([v,n])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="toggle-line"><span>目減りゼロ表示（新規提案）</span><input type="checkbox" id="demo-noloss" ${state.showNoLoss!==false?'checked':''}></label><label>比較する手数料率（試算例・％）<input type="number" id="demo-noloss-rate" min="0" max="50" value="${state.limits.compareFeeRate??10}"></label><label class="toggle-line"><span>SMS 本人確認 済み</span><input type="checkbox" id="demo-sms" ${state.user.sms?'checked':''}></label><label class="toggle-line"><span>インストール案件 解禁済み</span><input type="checkbox" id="demo-install" ${state.user.installUnlocked?'checked':''}></label><label>POPUP確認時刻（日本時間・空欄は現在時刻）<input type="time" id="demo-popup-time" value="${esc(state.popupTestTime||'')}"></label><p>表示頻度は管理画面で設定します。確認日と時刻で時間帯を切り替え、再読み込みして起動時の表示を確認できます。</p><label>表示する枠<select id="demo-popup-slot">${popupSlots(state).map((x,i)=>`<option value="${x.id}">${esc(x.name)}${i===0?'（自動表示の対象）':''}</option>`).join('')||'<option value="">表示できる枠がありません</option>'}</select></label>${button('起動時ポップアップを表示する','show-popup','btn secondary wide small')}${button('POPUPの表示回数をリセット','reset-popup','btn secondary wide small')}<div class="demo-actions"><b>アンケート会社の回答URL（空欄はデモ）</b>${surveys.map(q=>`<label>${esc(q.title)}<input type="url" data-survey-url="${esc(q.id)}" value="${esc(state.surveyResponseURLs?.[q.id]||'')}" placeholder="https://"></label>`).join('')}<b>ポイントの確定</b>${button(`ポイント自動判定を実行（${state.user.pendings.filter(x=>x.review==='auto').length}件）`,'auto-review','btn secondary wide small')}${button(`有人審査で承認（案件 ${state.user.pendings.filter(x=>x.review==='manual').length}件）`,'manual-review','btn secondary wide small')}<b>歩数・動画</b>${button('歩数を1,000歩進める','add-steps','btn secondary wide small')}${button('動画を本日の上限にする','limit-video','btn secondary wide small')}<b>案件の成果（NACS の承認・否認を再現）</b>${button('表示中の案件にテスト成果を作成','simulate-offer-result','btn secondary wide small')}${button('最新の案件の成果を承認（SUR は1段階）','progress-demo','btn secondary wide small')}${button('最新の案件の成果を否認','reject-demo','btn secondary wide small')}<b>チャレンジボーナス</b>${button('チャレンジボーナスを6件以上で確認','demo-six-challenges','btn secondary wide small')}${button('参加人数を+500人','advance-challenge','btn secondary wide small')}${button('達成にする（全件）','achieve-challenge','btn secondary wide small')}</div><div class="demo-foot"><b>仮値（spec は運用設定のため値を書かない）</b><p>歩数 ${LM.stepGoal.toLocaleString()}歩 × ${LM.stepMax/LM.stepGoal}回／動画あり ${yen(LM.stepRewardAd)}円相当・なし ${yen(LM.stepRewardNoAd)}円相当<br>動画 ${LM.videoLimit}回 × ${yen(LM.videoReward)}円相当<br>ミッション報酬 ${state.missionDef.map(m=>`${m.title.replace('よう','')} ${yen(m.reward)}`).join('・')}円相当<br>アンケート還元率 スクリーニング ${LM.surveyRate.screening}%・本調査 ${LM.surveyRate.main}%<br>これらは <a href="../mock-admin/" target="_blank">管理画面モック</a> から変更できます</p><b>spec に明記</b><p>最低交換 ${LM.minAmount}pt・交換単位 ${LM.unit}pt<br>インストール案件解禁：同日の動画視聴 ${LM.installUnlock}回</p></div>${button('デモデータを初期化','reset','text-link wide')}</aside>`;}



