function offerPreflightBody(id,status){
 const ios=(state.os||'ios')==='ios',allowed=status==='authorized',waiting=status==='loading';
 return `<p class="offer-preflight-copy">ポイントが正しく反映されるよう、<br>${ios?'以下2点':'以下'}をご確認ください</p><div class="offer-checks ${ios?'':'single'}"><div class="offer-check">${ios?'<span class="offer-check-number">1</span>':''}<b>Wi-Fiをオフ${ios?'':'にする'}<small>（推奨）</small></b><img src="assets/figma-offer/wifi-off-soft.svg" alt="Wi-Fiをオフにする"></div>${ios?`<div class="offer-check"><span class="offer-check-number">2</span><b>トラッキングを許可</b><small>${waiting?'確認中です':allowed?'※許可済みです':status==='restricted'?'※設定が制限されています':status==='unknown'?'※許可状態を確認できません':'※まだ許可されていません'}</small><div class="tracking-state-art" aria-hidden="true"><span>トラッキング</span><img src="assets/figma-offer/tracking-${allowed?'on':'off'}-soft.svg" alt=""></div></div>`:''}</div>${ios?`<p class="offer-tracking-help">より詳細な設定方法については、<br>${button('トラッキングの設定方法','offer-tracking-help','text-link',`data-id="${esc(id)}"`)}をご確認ください。</p>`:'<p class="offer-tracking-help">このあと、案件の申し込みページへ移動します。</p>'}${button(waiting?'確認中…':needsTracking(state.os||'ios',status)?'トラッキングの設定にすすむ':'今すぐチャレンジ！',needsTracking(state.os||'ios',status)?'offer-tracking-settings':'confirm-challenge','btn primary wide',`data-id="${esc(id)}" ${waiting?'disabled':''}`)}`;
}
async function showOfferPreflight(id){
 if(challengeState(state,id)!=='normal'){toast('この案件は現在チャレンジできません。');return;}
 preflightOffer=id;const version=++preflightVersion;
 offerSheet(offerPreflightBody(id,(state.os||'ios')==='ios'?'loading':'authorized'));
 if((state.os||'ios')!=='ios')return;
 const status=await readTracking(window.pochipoNative,state.trackingPermission);
 if(version!==preflightVersion||!modal.open||preflightOffer!==id)return;
 offerSheet(offerPreflightBody(id,status));
}
function showTrackingHelp(id){
 if(preflightOffer!==id)return;
 preflightVersion++;
 offerSheet(`<p class="offer-preflight-copy">iPhoneの「設定」でトラッキングを許可してください。</p><ol class="tracking-settings-steps"><li>「設定」→「プライバシーとセキュリティ」→「トラッキング」を開く</li><li>「アプリからのトラッキング要求を許可」をオンにする</li><li>「タメルコ」の許可をオンにする</li></ol><p class="tiny">制限により変更できない場合は、端末の管理者やAppleの案内をご確認ください。</p>${!window.pochipoNative?'<p class="info-box">WebモックからiPhoneの設定は開けません。上の手順で設定を確認できます。画面の分岐は「デモ設定」のトラッキング項目で試せます。</p>':''}${button('設定を確認して戻る','offer-preflight-return','btn primary wide',`data-id="${esc(id)}"`)}`,'offer-settings-help');
}
async function openOfferSettings(id){
 if(preflightOffer!==id||!modal.open||offerOpening)return;
 if(typeof window.pochipoNative?.openTrackingSettings!=='function'){showTrackingHelp(id);return;}
 offerOpening=true;const version=preflightVersion;
 try{const opened=await window.pochipoNative.openTrackingSettings();if(preflightOffer!==id||version!==preflightVersion)return;if(opened===false)showTrackingHelp(id);}
 catch{if(preflightOffer===id&&version===preflightVersion)showTrackingHelp(id);}
 finally{offerOpening=false;}
}
async function openOfferApplication(id){
 if(preflightOffer!==id||!modal.open||offerOpening)return;
 offerOpening=true;const version=preflightVersion;
 try{
  const status=(state.os||'ios')==='ios'?await readTracking(window.pochipoNative,state.trackingPermission):'authorized';
  if(preflightOffer!==id||version!==preflightVersion||!modal.open)return;
  const offer=offersOf(state).find(o=>o.id===id),decision=outboundDecision(state,offer,status);
  if(decision.error){toast(decision.error);return;}
  if(decision.settings){await showOfferPreflight(id);return;}
  if(challengeState(state,id)!=='normal'){toast('この案件は現在チャレンジできません。');return;}
  // Only a click is recorded. Receipt of a conversion is a separate NACS event.
  recordClick(state,id);save();close();window.location.assign(decision.url);
 }finally{offerOpening=false;}
}
