async function playAd(retryAction,retryId){
 const retry=()=>handleAction(retryAction,retryId);
 const failure=adFailure;adFailure='none';
 for(const select of document.querySelectorAll('#demo-ad-error'))select.value='none';
 const error=adErrorFor({online:navigator.onLine,ads:adsAllowed(state),failure,scenario:state.scenario});
 if(error){showFigmaDialog(error,{retry});return false;}
 showModal('デモ動画を再生中',`<div class="video-screen">${icon('play')}<p>サンプル広告</p><div class="video-progress"></div></div><p class="tiny">${state.user.dailyMissionJourney?.kind==='video'?'視聴完了後はデイリーミッションの一覧で受け取れます。':'視聴完了後にポイントを獲得できます。'}途中で閉じると何も起きません。</p>`);
 const token=crypto.randomUUID(),startedDate=state.date;modal.dataset.videoToken=token;await wait(2000);
 if(!modal.open||modal.dataset.videoToken!==token||state.date!==startedDate)return false;
 if(!navigator.onLine){showFigmaDialog('ad-network',{retry});return false;}
 if(failure==='reward-failed'){showFigmaDialog('reward-failed',{retry});return false;}
 return true;
}

