document.addEventListener('click',e=>{const surveyLink=e.target.closest('a[href^="#answer/"]');if(surveyLink){e.preventDefault();openSurvey(decodeURIComponent(surveyLink.getAttribute('href').slice(8)));return;}if(e.target.closest('a[href^="#"]'))navigation.capture(currentPageView());},true);
window.addEventListener('pagehide',()=>navigation.capture(currentPageView()));

document.addEventListener('click',async e=>{const card=e.target.closest('[data-survey-card]');if(card&&!e.target.closest('[data-action]')){await openSurvey(card.dataset.surveyCard);return;}const el=e.target.closest('[data-action]');const slotLink=e.target.closest('[data-slot]');const pill=e.target.closest('[data-attention-pill]');if(pill&&!isBannerPreview){attention=readAttention(state,localStorage);markPillRead(attention,attentionItems,pill.dataset.attentionPill);persistAttention();pill.querySelectorAll('.attention-dot,.attention-copy').forEach(x=>x.remove());}if(slotLink){record(state,slotLink.dataset.slot,'tap');save();}if(el){if(el.dataset.action==='challenge-help')e.preventDefault();await handleAction(el.dataset.action,el.dataset.id,el);}});
async function handleAction(a,id,el={dataset:{}}){
 if(a.startsWith('oem-')){exchangeOEM.handle(a,id);return;}
 switch(a){
 case'dismiss-goal-hint':goalHintUntil=0;document.querySelector('.goal-hint')?.classList.add('is-dismissing');break;
 case'point-filter':pointFilter=el.dataset.value;render();break;
 case'point-history':pointVisibleCount=20;go('points');break;
 case'point-more':pointVisibleCount+=20;render();break;
 case'side-pop':sidePopOpen=!sidePopOpen;render();break;
 case'noop':break;
 // --- デイリーミッション ---
 case'chat-answer':{const topic=chatTopics.find(t=>t.id===id);if(!topic)break;const sessions=state.chatSessions??={};const answers=sessions[id]||[];if(answers.length!==Number(el.dataset.step))break;sessions[id]=answerChat(topic,answers,Number(el.dataset.index));save();render();const target=document.querySelector('.chat-answer-box button,.chat-results a');target?.focus({preventScroll:true});document.querySelector('.chat-answer-box,.chat-results')?.scrollIntoView({behavior:'smooth',block:'center'});break;}
 case'chat-reset':{if(state.chatSessions)delete state.chatSessions[id];save();render();document.querySelector('.phone-scroll').scrollTop=0;break;}
 case'home-tab':go(el.dataset.value==='survey'?'surveys/home':'home/'+el.dataset.value);break;
 case'copy-invite':{const code=registerInviteCode(state);save();try{await navigator.clipboard.writeText(code);toast('紹介コードをコピーしました');}catch{showModal('紹介コード', `<p>コードを選択してコピーしてください。</p><input aria-label="紹介コード" value="${esc(code)}" readonly>`);}break;}
 case'mission-start':{const journey=beginMissionActivity(state,id,currentPageView());if(journey.error){refreshCurrentPage();break;}save();if(journey.kind==='video')await enterMissionVideo();else if(['survey','minigame'].includes(journey.kind)){delete state.user.dailyMissionJourney;save();go(journey.kind==='survey'?'surveys':'home/minigames/list');}else go(journey.to);break;}
 case'claim-mission':{const latest=JSON.parse(localStorage.getItem(KEY)||'null');if(latest&&latest.accountAuth?.active===state.accountAuth?.active){state=latest;initAccounts(state);}const r=claimMission(state,id,{date:el?.dataset.date||state.date});if(r.error){refreshCurrentPage();toast(r.error==='ERROR_TYPE_DAILY_MISSION_TASK_ALREADY_CLAIMED'?'すでに受け取り済みです。':'このタスクはまだ受け取れません。');break;}save();earnedDialog(r.amount,'デイリーミッション',{missionClaim:true,missionId:id});break;}
 // --- 歩いてためる ---
 case'scroll-walk':case'go-walk':go('home/steps');break;
 case'step-select':{const permission=walkPermissionDialog(state);if(permission){showFigmaDialog(permission);break;}if(!stepsClaimable(state)){toast('獲得可能なマイルストーンがありません。');break;}showFigmaDialog('step-select');break;}
 case'step-noad':{const amt=claimSteps(state,false);if(amt){save();render();earnedDialog(amt,'歩いてためる');}else{close();toast('獲得できませんでした。');}break;}
 case'step-ad':{const ok=await playAd(a,id);if(!ok)break;const amt=claimSteps(state,true);if(amt){save();render();earnedDialog(amt,'歩いてためる（動画あり）');}else{close();toast('獲得できませんでした。');}break;}
 case'walk-link':{const id=walkPermissionDialog(state);if(id)showFigmaDialog(id);break;}
 case'walk-link-ok':state.stepLink='linked';close();updated('歩数の利用を許可しました（モック）。');break;
 case'walk-link-deny':state.stepLink='denied';close();updated('歩数を利用せずに続けます。あとから設定を確認できます。');break;
 case'walk-connection-help':showModal('歩数の連携について',`<p>歩数データへのアクセスを許可すると、今日の歩数と達成状況が表示されます。</p><ol><li>「歩数を連携する」をタップします。</li><li>端末に表示される案内に従って、歩数へのアクセスを許可します。</li><li>画面に戻って歩数を確認します。</li></ol><p>1,000歩ごとに達成状況を確認でき、1日の目標は10,000歩です。</p><p class="tiny">この画面はモックです。端末のヘルスケアや身体活動データには実際にアクセスせず、右側の確認パネルで連携状態と歩数を再現します。</p>`);break;
 case'walk-help':showModal('歩いてためる',`<p>${L(state).stepGoal.toLocaleString()}歩ごとのマイルストーンに到達するとポイントを獲得できます（1日${stepMaxCount(state)}回まで）。到達済みの1段階ごとに動画を視聴して受け取ります。</p><p>歩数は端末が計測した当日の歩数を使い、日付は JST 0:00 で切り替わります。ポイントは付与予定として登録され、判定後に交換可能になります。</p><div class="info-box">間隔・上限回数・ポイント額は運用設定です（このモックの値は仮値）。実際のヘルプは Zendesk のヘルプページで案内します。</div>${button('閉じる','close','btn primary wide')}`);break;
 // --- 動画リワード ---
 case'mission-video':await enterMissionVideo();break;
 case'video':{if(videoBusy)break;videoBusy=true;try{if(!adsAllowed(state)){showFigmaDialog('ad-empty');break;}if(videoRemaining(state)<=0){toast('本日分は終了しました。');break;}const origin=videoMissionOrigin||{hash:location.hash||'#home',view:currentPageView()};const journey=state.user.dailyMissionJourney?.kind==='video'?{...state.user.dailyMissionJourney}:null;const ok=await playAd(a,id);if(!ok)break;const before=missionTasks(state).done;if(claimVideo(state,{mission:journey})){save();if(journey){returnToDailyMissions();break;}videoMissionOrigin=null;navigation.replace(origin.hash);restorePageView(origin.view);render();restorePagePosition(origin.view);earnedDialog(L(state).videoReward,'動画を見てためる',{missionCompleted:missionTasks(state).done>before});}else{close();toast('現在、この動画は完了できません。ミッション一覧からやり直してください。');}}finally{videoBusy=false;}break;}
 // --- 案件 ---
 case'sur-progress-toggle':toggleSurProgress(el);break;
 // spec affiliate-detail 4：「今すぐチャレンジ！」→ 広告トラッキング確認シート → 署名付きクリック URL を取得し外部ブラウザで開く
 case'challenge':recordOfferButton(state,id,'click');save();await showOfferPreflight(id);break;
 case'confirm-challenge':await openOfferApplication(id);break;
 case'offer-tracking-settings':await openOfferSettings(id);break;
 case'offer-tracking-help':showTrackingHelp(id);break;
 case'offer-preflight-return':await showOfferPreflight(id);break;
 case'simulate-offer-result':{const offerId=route()[0]==='offer'?route()[1]:null;if(!offerId){toast('案件詳細を開いてから実行してください。');break;}try{const cv=challenge(state,offerId);if(cv)updated('検証用の成果を作成しました。実際の申し込み・付与は行いません。');else toast('この案件は現在チャレンジできません。');}catch(error){toast(error.message);}break;}
 case'case-tab':caseTab=restoredCaseTab(el.dataset.value);render();document.querySelector('.phone-scroll').scrollTop=0;document.querySelector(`[data-action="case-tab"][data-value="${caseTab}"]`)?.focus({preventScroll:true});break;
 case'case-support':await openCaseHelp();break;
 case'case-help':showModal('ポイントが貯まるまで',`<ol class="steps"><li><b>成果ステータスを確認</b><span>判定中→承認／否認の順に進みます。承認までの目安は案件詳細に記載しています。</span></li><li><b>承認後のポイント</b><span>付与予定（準備中）に登録され、審査後に交換可能へ移ります。マイ案件の「承認」表示が先になることがあります。</span></li><li><b>反映されないとき</b><span>タメルコの「ポイントゲット」から利用したか、獲得条件・対象外条件をご確認ください。</span></li></ol>${button('閉じる','close','btn primary wide')}`);break;
 case'offer-reset':category='すべて';search='';if(route()[0]!=='offers')go('offers');else render();break;
 case'offer-guide':showModal('お得の使い方',`<div class="info-box">${operationSettings(state).guide.split('\n').map(x=>`<p>${esc(x)}</p>`).join('')}</div>${button('閉じる','close','btn primary wide')}`);break;
 case'challenge-help':case'challenge-guide':await openChallengeHelp();break;
 case'slide':carousel=+el.dataset.index;render();break;
 case'category':category=el.dataset.value;render();break;
 case'ranking-category':rankingCategory=el.dataset.value;refreshCurrentPage();break;
 case'survey-filter':surveyFilter=el.dataset.value;render();break;
 // --- アンケート ---
 case'open-survey':await openSurvey(id,el);break;
 case'close-survey':{if(state.user.dailyMissionJourney?.kind==='survey'){returnToDailyMissions();break;}const pending=state.user.surveyMissionPermissionPending;delete state.user.surveyMissionPermissionPending;save();navigation.capture(currentPageView());navigation.back('surveys');if(pending)permissionFlow.afterReward({source:'survey',missionCompleted:true});break;}
 case'answer':{const value=+el.dataset.value;answerDraft.answers[answerDraft.step]=value;render();document.querySelector(`[data-action="answer"][data-value="${value}"]`)?.focus({preventScroll:true});break;}
 case'previous-question':answerDraft.step--;render();break;
 case'next-question':{if(['interrupted','ended'].includes(state.surveyPreview)){navigation.replace('#surveys');render();break;}const q=surveys.find(x=>x.id===answerDraft.id);if(answerDraft.answers[answerDraft.step]===undefined)break;if(answerDraft.step<q.questions.length-1){answerDraft.step++;render();}else{showModal('回答を送信しています',`<div class="loading-state"><div class="spinner"></div><p>回答完了の通知を待っています…</p></div>`);modal.querySelector('[data-action="close"]').disabled=true;await wait(1100);if(state.scenario==='error'){showModal('送信できませんでした',`<p>回答内容は保持されています。もう一度お試しください。</p>${button('再送信する','retry-submit','btn primary wide')}`);}else{const missionBefore=missionTasks(state).done;const journey=state.user.dailyMissionJourney?.kind==='survey'?{...state.user.dailyMissionJourney}:null;const amount=completeSurvey(state,q.id,{mission:journey});if(journey){if(amount)returnToDailyMissions();else{close();toast('ミッション一覧からやり直してください。');}}else{if(missionTasks(state).done>missionBefore)state.user.surveyMissionPermissionPending=true;save();close();navigation.replace(`complete/${q.id}`);render();}}}break;}
 case'retry-submit':state.scenario='normal';close();save();document.querySelector('[data-action="next-question"]')?.click();break;
 case'interrupt':showModal('回答を中断しますか？',`<p>このタブを開いている間は、途中から再開できます。</p>${button('アンケート一覧へ戻る','confirm-interrupt','btn secondary wide')}${button('回答を続ける','close','btn primary wide')}`);break;
 case'confirm-interrupt':if(state.user.dailyMissionJourney?.kind==='survey'){returnToDailyMissions();break;}close();navigation.capture(currentPageView());navigation.back('surveys');break;
 case'retry':state.scenario='normal';updated('再読み込みしました。');break;
 case'restore-view':viewState='normal';render();break;
 case'profile':showModal('プロフィールを確認する',`<p>プロフィール（属性情報）が登録されると、対象のアンケートをご案内しやすくなります。</p><div class="info-box">モックでは架空のプロフィールを使用します。初回登録の報酬は現行仕様にない新機能の提案です（${pt(1000)}pt・仮値）。</div><ul class="profile-fields"><li>年代 <b>30代（サンプル）</b></li><li>居住地域 <b>関東（サンプル）</b></li><li>世帯 <b>2人（サンプル）</b></li><li>性別 <b>回答しない（サンプル）</b></li></ul>${button(state.user.profile?'登録済み':'サンプルで登録を試す','save-profile','btn primary wide',state.user.profile?'disabled':'')}`);break;
 case'save-profile':if(!state.user.profile){state.user.profile=true;schedule(state,'アンケートで獲得',1000,'SURVEY','auto','初回プロフィール登録（モニタ情報取得）');close();save();render();earnedDialog(1000,'プロフィール登録');}break;
 // --- マイページ・ポイント ---
 case'balance':showModal('ポイントの内訳',`<div class="balance-lines"><div><span>合算ポイント</span>${money(total(state),'m-row')}</div><div><span>交換可能（保有）</span>${money(state.user.approved,'m-row')}</div><div><span>準備中（付与予定）</span>${money(state.user.pending,'m-row')}</div><div><span>累計（総獲得）</span>${money(state.user.earned,'m-row')}</div></div><p>準備中のポイントは、ポイント自動判定または審査で確定すると交換可能に移ります。交換できるのは交換可能のポイントだけです。</p>`);break;
 case'exchange':close();go('exchange-destinations');break;
 case'dotmoney':go('points');break;
 case'invite-entry':close();go('account/invite');break;
 case'mypage-setting':{const label=el.dataset.label;if(label==='通知設定'){showModal('通知設定',`<p>アプリからのお知らせを${operationSettings(state).notificationsEnabled?'受け取る':'停止する'}設定です。</p>${button(operationSettings(state).notificationsEnabled?'通知を停止する':'通知を受け取る','toggle-notification','btn primary wide')}`);break;}const documentURL=operationSettings(state)[label==='利用規約'?'termsURL':label==='プライバシーポリシー'?'privacyURL':''];if(documentURL&&/^https:\/\//.test(documentURL)){window.open(documentURL,'_blank','noopener');break;}if(label==='アカウント情報'){close();go('account/profile');break;}const message=label==='トラッキング設定'?'iPhoneでは「設定」からアプリのトラッキング設定を確認できます。このWebモックから端末設定の変更はできません。':'公開用の'+label+'は準備中です。正式な内容の接続後にこの画面から確認できます。';showModal(label,`<p>${esc(message)}</p>${button('閉じる','close','btn primary wide')}`);break;}
 case'guest-help':showModal('ゲストユーザーについて',`<p>ゲストのままでもポイントをためられます。会員登録すると、ためたポイントと履歴を引き継いで利用できます。</p>${button('閉じる','close','btn primary wide')}`);break;
 case'guest-signup':close();accountUI.start('signup');break;
 case'guest-promote':close();accountUI.start('signup');break;
 case'help':showModal('ヘルプ',`<div class="info-box">${operationSettings(state).help.split('\n').map(x=>`<p>${esc(x)}</p>`).join('')}</div>${button('お問い合わせ','contact','btn primary wide')}`);break;
 case'contact':{const url=operationSettings(state).contactURL;if(url&&/^https:\/\//.test(url))window.open(url,'_blank','noopener');else showModal('お問い合わせ',`<p>会員ID・案件名・利用日時を添えてお問い合わせください。</p><p>お問い合わせ窓口は準備中です。</p>${button('閉じる','close','btn primary wide')}`);break;}
 case'noloss':{const v=noLossView(state,total(state));showModal('ためた分が、そのまま受け取れます',`<div class="noloss-sheet"><p class="lead">タメルコは、ポイントの交換で<b>手数料 0円・100pt = 1円相当</b>。ためたポイントの円相当が、そのまま受け取額になります。</p><div class="ba sheet"><div class="ba-before"><small>ためたポイント</small><b>${pt(total(state))}pt</b></div><span class="ba-arrow">${icon('arrow')}</span><div class="ba-after"><small>交換時の円相当額</small><del>${yen(v.compare)}円相当</del><b>${yen(v.net)}円相当</b></div></div><p class="ba-note">取り消し線の <b>${yen(v.compare)}円相当</b> は、手数料 ${v.rate}% の場合の試算例（−${yen(v.loss)}円相当）。タメルコは手数料 0円なので、ためた ${yen(total(state))}円相当 がそのまま交換時の円相当額になります。</p><ul class="cond-list"><li class="ok">${icon('check')}交換手数料 0円</li><li class="ok">${icon('check')}100pt = 1円相当</li><li class="ok">${icon('check')}最低交換 ${pt(L(state).minAmount)}pt・交換単位 ${pt(L(state).unit)}pt</li></ul><p class="tiny">※「手数料 ${v.rate}% の場合」は試算例です。各ポイント・ギフトへの交換レートは、交換先の条件によります。</p></div>`);break;}
 case'savings':showModal('交換手数料無料',`<div class="reward-dialog"><h3>ポイントの交換で、<br>手数料はかかりません。</h3><p>交換単位 ${pt(L(state).unit)}pt = 1円相当。最低交換ポイントは ${pt(L(state).minAmount)}pt です。</p><p class="tiny">確定したポイントには有効期限（確定から N ヶ月後の月末。N は運用設定）があります。</p></div>`);break;
 case'toggle-notification':operationSettings(state).notificationsEnabled=!operationSettings(state).notificationsEnabled;save();close();toast('通知設定を変更しました。');break;
 case'notifications':go('notifications');break;
 case'chinchiro':{
  const game=selectedMiniGame();
  if(!game){close();go('home/minigames');break;}
  if(chinchiroBusy)break;
  const st=gameStatus(state,game.id);
  if(!st.visible){toast(game.title+'は現在停止中です。');break;}
  showMiniGame(game,miniGameView(game).sheet(st));break;
 }
 case'chinchiro-retry':{
  const game=selectedMiniGame();if(!game||chinchiroBusy)break;
  const st=gameStatus(state,game.id);if(!st.visible)break;
  showMiniGame(game,miniGameView(game).choice(st));break;
 }
 case'dice-finish':{
  if(chinchiroBusy||selectedMiniGame()?.id!=='dice')break;
  const st=gameStatus(state,'dice');if(st.remaining>0||st.used!==3)break;
  const held=gameHeld(state,'dice');if(!held)break;
  held.deferred=true;save();render();
  document.querySelector('.chinchiro-stage')?.focus({preventScroll:true});break;
 }
 case'mini-games-list':close();go(miniGamesEntry(state));break;
 case'mini-games-home':close();go('home');break;
 case'mini-games-mode':{if(chinchiroBusy){toast('演出・動画の終了後に切り替えてください。');break;}setMiniGamesMode(state,el.dataset.value);close();save();go(miniGamesEntry(state));render();break;}
 case'chinchiro-boost':case'chinchiro-roll':{
  const game=selectedMiniGame();if(!game||chinchiroBusy)break;
  chinchiroBusy=true;
  const startedState=state,startedDate=state.date,startedRoute=location.hash;
  try{
   const st=gameStatus(state,game.id);
   if(!st.visible||st.remaining<=0){toast('本日の挑戦は終了しました');break;}
   if(a==='chinchiro-boost'&&!await playAd(a,id))break;
   if(state!==startedState||state.date!==startedDate||location.hash!==startedRoute)break;
   const result=drawGame(state,game.id,a==='chinchiro-boost');save();render();
   const host=showMiniGame(game,miniGameView(game).sheet(gameStatus(state,game.id),result,true));
   if(!host)break;
   host.dataset.gameRoll=result.id;
   await wait(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?60:game.id==='roulette'?3000:game.id==='dice'?DICE_ROLL_MS:CHINCHIRO_ROLL_MS);
   if(host.isConnected&&host.dataset.gameRoll===result.id&&state===startedState&&state.date===startedDate&&location.hash===startedRoute){
    showMiniGame(game,miniGameView(game).sheet(gameStatus(state,game.id),result));
    host.focus({preventScroll:true});
   }
  }catch(err){toast(err.message);}finally{chinchiroBusy=false;}break;
 }
 case'chinchiro-claim':{
  const game=selectedMiniGame();if(!game||chinchiroBusy)break;
  const held=gameHeld(state,game.id);if(!held)break;
  const startedState=state,startedRoute=location.hash;
  chinchiroBusy=true;
  try{
   if(!await playAd(a,id))break;
   if(state!==startedState||location.hash!==startedRoute)break;
   if(claimGame(state,game.id,held.id)){
    save();render();showFigmaDialog('earned',{amount:held.amount,miniGameRemaining:gameStatus(state,game.id).remaining,miniGameSingle:miniGamesMode(state)==='tier1',miniGameId:game.id});
   }
  }catch(err){toast(err.message);}finally{chinchiroBusy=false;}break;
 }
 case'report':{const today=state.user.history.filter(x=>x.date===state.date&&x.amount>0);const total_=today.reduce((s,x)=>s+x.amount,0);showModal('今日の実績',`<div class="share-card"><div class="share-top"><span class="wordmark">${coin()}タメルコ</span><span>${state.date.replaceAll('-','.')}</span></div><h3>今日の獲得状況</h3>${money(total_,'m-balance')}<p>${today.length}件のお仕事（確定・準備中を含む）</p><small>※円相当は交換・換金後の概算値です。</small></div>${button(`${icon('download')}実績カードを保存`,'download-report','btn primary wide')}<p class="tiny">画像（SVG）として保存します。実績レポート画面（月別集計・履歴）は次の制作範囲です。</p>`);break;}
 case'download-report':{const rows=state.user.history.filter(x=>x.date===state.date&&x.amount>0),total_=rows.reduce((s,x)=>s+x.amount,0);download(`tameruko-${state.date}.svg`,`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="800"><rect width="800" height="800" rx="40" fill="#e8f6f0"/><g fill="#12806b" font-family="sans-serif"><text x="64" y="110" font-size="40" font-weight="bold">タメルコ</text><text x="64" y="190" font-size="24">${state.date}</text><text x="64" y="300" font-size="48">今日の獲得状況</text><text x="64" y="440" font-size="96" font-weight="bold">${yen(total_)}</text><text x="64" y="505" font-size="28">円相当のお小遣い</text><text x="64" y="600" font-size="30">${rows.length}件のお仕事</text><text x="64" y="714" font-size="18">※円相当は交換・換金後の概算値です。デモ実績。</text></g></svg>`,'image/svg+xml');toast('実績カードを保存しました。');break;}
 // --- ポップアップ ---
 case'show-popup':{const pid=document.querySelector('#demo-popup-slot')?.value;const slot=popupSlots(state).find(x=>x.id===pid)||popupSlots(state)[0];if(!slot){toast('表示できるポップアップ枠がありません。');break;}close();await wait(60);showPopup(slot,{markSeen:false});break;}
 case'reset-popup':state.user.popupImpressions=[];state.user.daily[state.date]={...day(state),popupSeen:false};updated('ポップアップの表示回数をリセットしました。');break;
 case'popup-go':record(state,el.dataset.slot,'tap');close();break;
 // --- デモ操作 ---
 case'auto-review':{const n=autoReview(state);updated(n?`ポイント自動判定を実行し、${n}件を交換可能にしました。`:'自動判定の対象（準備中）はありません。');break;}
 case'manual-review':{const n=manualReview(state);updated(n?`有人審査で${n}件を承認し、交換可能にしました。`:'審査待ちの案件ポイントはありません。');break;}
 case'add-steps':addSteps(state,1000);updated(`歩数を${day(state).steps.toLocaleString()}歩にしました。`);break;
 case'limit-video':state.user.daily[state.date]={...day(state),video:L(state).videoLimit};updated('本日の動画上限に切り替えました。');break;
 case'progress-demo':{const c=[...state.user.cases].reverse().find(x=>['challenging','judging'].includes(x.status));if(!c){toast('承認できる成果がありません。先に案件にチャレンジしてください。');break;}progressOffer(state,c.offerId);updated(`「${c.name}」の成果を承認しました。付与予定（審査）に登録されます。`);break;}
 case'reject-demo':{const c=[...state.user.cases].reverse().find(x=>['challenging','judging'].includes(x.status));if(!c){toast('否認できる成果がありません。');break;}rejectOffer(state,c.offerId);updated(`「${c.name}」の成果を否認しました。`);break;}
 case'advance-challenge':{const paid=advanceChallenges(state,500);updated(paid?`参加人数を更新し、達成分のボーナスを${paid}件登録しました。`:'チャレンジの参加人数を+500人にしました。');break;}
 case'achieve-challenge':{const paid=achieveChallenges(state);updated(paid?`すべてのチャレンジを達成にし、承認済み案件のボーナスを${paid}件登録しました。`:'すべてのチャレンジを達成にしました。成果の承認後にボーナスが登録されます。');break;}
 case'dialog-preview':showFigmaDialog(id,{preview:true,amount:30,balance:100,adReward:30,noAdReward:5,ads:true});break;
 case'dialog-preview-action':close();toast('表示確認です。ポイント・権限・日付は変更していません。');break;
 case'dialog-retry':{const retry=dialogRetry;close();if(retry)await retry();else render();break;}
 case'dialog-permission':showModal('歩数連携を試す',`<p>Webモックでは端末の設定画面を開けません。連携後の表示を確認できます。</p>${button('連携済みとして試す','walk-link-ok','btn primary wide')}${state.os==='android'?button('許可しない場合の案内を見る','dialog-permission-denied','btn secondary wide'):''}${button('許可しない','walk-link-deny','btn secondary wide')}${button('キャンセル','close','text-link wide')}`);break;
 case'dialog-permission-denied':showFigmaDialog('health-android-settings');break;
 case'demo':showModal('モックの検証設定',demoPanel());break;
 case'reset':showModal('デモデータを初期化',`<p>このモック内の回答・残高・成果を初期状態へ戻します。</p>${button('初期化する','confirm-reset','btn primary wide')}`);break;
 case'demo-screens':showModal('画面一覧',inspector());break;
 case'demo-six-challenges':{localStorage.setItem(KEY+':before-challenge-demo',JSON.stringify(state));configureChallengeDemo(state);viewState='normal';close();save();navigation.replace('#offers-list/challenge');render();toast('チャレンジボーナスの一覧を表示しました。');break;}
 case'demo-five-missions':{localStorage.setItem(KEY+':before-five-missions',JSON.stringify(state));configureFiveMissionDemo(state,crypto.randomUUID());answerDraft=null;viewState='normal';close();save();navigation.replace('#home/daily');render();toast('登録済みのデイリーミッション5件をすべて表示しました。');break;}
 case'reset-daily-missions':{localStorage.setItem(KEY+':before-mission-reset',JSON.stringify(state));resetDailyMissionDemo(state,crypto.randomUUID());answerDraft=null;viewState='normal';close();save();navigation.replace('#home/daily');render();toast('デイリーミッションを未完了に戻しました。');break;}
 case'confirm-reset':expandedCategories={};localStorage.removeItem(ATTENTION_KEY);state=initialState();initAccounts(state,{fresh:true});answerDraft=null;viewState='normal';caseTab='challenging';category='すべて';search='';carousel=0;close();updated('初期状態に戻しました。');go('onboarding/1');break;
 case'page-back':if(route()[0]==='points'&&!route()[1]&&reportAdView?.user===state.user)reportAdBack={...reportAdView};navigation.capture(currentPageView());navigation.back(el.dataset.fallback);break;
 case'close':close();break;
 }
}
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-survey-url]')){state.surveyResponseURLs??={};state.surveyResponseURLs[t.dataset.surveyUrl]=t.value.trim();save();return;}switch(t.id){case'demo-survey-preview':state.surveyPreview=t.value;viewState='normal';state.scenario='normal';break;case'demo-view':viewState=t.value;break;case'demo-date':if(t.value&&t.value!==state.date){state.date=t.value;save();render();showFigmaDialog('date-change',{retry:()=>render()});}return;case'demo-ad-error':adFailure=t.value;return;case'demo-os':state.os=t.value;break;case'demo-tracking':state.trackingPermission=t.value;break;case'demo-persona':state.persona=t.value;if(t.value==='new')state.user.installUnlocked=false;if(t.value==='regular')state.user.installUnlocked=true;break;case'demo-steplink':state.stepLink=t.value;updated('歩数の許諾状態を切り替えました。');if(modal.open)close();maybeShowWalkPermission();return;case'demo-scenario':state.scenario=t.value;break;case'demo-noloss':state.showNoLoss=t.checked;break;case'demo-noloss-rate':state.limits.compareFeeRate=Math.max(0,Math.min(50,Number(t.value)||0));break;case'demo-sms':state.user.sms=t.checked;break;case'demo-install':state.user.installUnlocked=t.checked;break;case'demo-popup-time':state.popupTestTime=t.value;break;case'demo-popup-slot':return;default:return;}updated('確認条件を切り替えました。');});
document.addEventListener('toggle',e=>{if(e.target.isConnected&&e.target.matches('details[data-category-more]'))expandedCategories[e.target.dataset.categoryMore]=e.target.open;},true);
document.addEventListener('submit',e=>{if(e.target.id==='report-goal-form'){e.preventDefault();const goal=Number(new FormData(e.target).get('goal'));if(Number.isInteger(goal)&&goal>0&&goal<=10000000){state.user.reportGoal=goal;save();render();toast('目標を設定しました');}return;}if(e.target.id==='search-form'){e.preventDefault();search=new FormData(e.target).get('search').trim();render();}});
modal.addEventListener('close',()=>{if(!modal.open){stopRewardMotion();modal.dataset.videoToken='';updateAttentionForView();document.querySelectorAll('.attention-dot,.attention-copy').forEach(x=>x.remove());refreshAttentionDots();restoreDialogFocus();}});
modal.addEventListener('cancel',e=>{if(permissionFlow.active||rewardPermissionContext||missionRewardReturn){e.preventDefault();close();}preflightOffer=null;preflightVersion++;modal.dataset.videoToken='';});
modal.addEventListener('click',e=>{if(e.target.closest('a[href^="#"]'))close();else if(e.target===modal){if(modal.classList.contains('figma-dialog')){close();return;}const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
window.addEventListener('hashchange',()=>{videoMissionOrigin=null;const previousView=navigation.arrive(currentPageView());restorePageView(previousView);if(preflightOffer)close();sidePopOpen=false;const returning=reportAdBack;reportAdBack=null;render();restorePagePosition(previousView);maybeShowWalkPermission();if(returning?.user===state.user&&!(route()[0]==='points'&&!route()[1])){queueReportReturnAd(state,returning.through);save();}requestWorkInterstitial();});
window.addEventListener('focus',()=>{if(!state.user.surveyMissionPermissionPending||modal.open)return;delete state.user.surveyMissionPermissionPending;save();permissionFlow.afterReward({source:'survey',missionCompleted:true});});
window.addEventListener('storage',e=>{if(!isBannerPreview&&e.key===ATTENTION_KEY){refreshCurrentPage();return;}if(!isBannerPreview&&e.key===KEY){state=JSON.parse(e.newValue)||initialState();initAccounts(state);if(retireTravelBoostPreview(state))save();if(state.user.dailyMissionJourney?.completed){returnToDailyMissions();return;}refreshCurrentPage();}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){refreshCurrentPage();if(preflightOffer&&modal.open&&modal.classList.contains('offer-preflight'))showOfferPreflight(preflightOffer);}});
if(accountFreshStart&&!isBannerPreview&&!location.hash)navigation.replace('#onboarding/1');
if(state.user.dailyMissionJourney?.completed)returnToDailyMissions();
save();render();
const dialogPreviewId=new URLSearchParams(location.search).get('dialog');
if(dialogDefinitions[dialogPreviewId])showFigmaDialog(dialogPreviewId,{preview:true,amount:30,balance:100,adReward:30,noAdReward:5,ads:true});
else maybeShowWalkPermission();
// 起動時は管理画面の頻度に従う。他のダイアログには割り込まない。
setTimeout(()=>{launchAdPending=false;if(!isBannerPreview&&route()[0]==='home'&&adsAllowed(state)&&viewState==='normal'&&state.scenario!=='error')showPopup(launchPopup(state));requestWorkInterstitial();},350);

// タッチとマウスの横スワイプ。縦スクロールと案件カルーセルは維持する。
let homePointer=null, suppressHomeClick=false;
document.addEventListener('pointerdown',e=>{homePointer=null;suppressHomeClick=false;if(!e.isPrimary||e.button!==0||!e.target.closest('.home-panel')||e.target.closest('.hscroll,.chat-room,input,button'))return;homePointer={id:e.pointerId,x:e.clientX,y:e.clientY};});
document.addEventListener('pointerup',e=>{if(!homePointer||homePointer.id!==e.pointerId)return;const dx=e.clientX-homePointer.x,dy=e.clientY-homePointer.y;homePointer=null;if(route()[0]!=='home'||Math.abs(dx)<55||Math.abs(dx)<Math.abs(dy)*1.5)return;suppressHomeClick=true;const i=Math.max(0,HT().findIndex(([k])=>k===route()[1]));const next=i+(dx<0?1:-1);if(HT()[next])go('home/'+HT()[next][0]);setTimeout(()=>{suppressHomeClick=false;},0);});
document.addEventListener('pointercancel',()=>{homePointer=null;});
document.addEventListener('dragstart',e=>{if(e.target.closest('.home-panel')&&!e.target.closest('.hscroll,.banner-carousel'))e.preventDefault();});
document.addEventListener('click',e=>{if(suppressHomeClick){e.preventDefault();e.stopImmediatePropagation();suppressHomeClick=false;}},true);
document.addEventListener('keydown',e=>{const tab=e.target.closest('.home-tabs [role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=HT().findIndex(([k])=>k===tab.dataset.value);const next=e.key==='Home'?0:e.key==='End'?HT().length-1:(i+(e.key==='ArrowRight'?1:-1)+HT().length)%HT().length;go('home/'+HT()[next][0]);setTimeout(()=>document.querySelector('#tab-'+HT()[next][0])?.focus({preventScroll:true}),50);});

if(isBannerPreview)window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==(window.opener||window.parent)||e.data?.type!=='campaign-preview')return;state=structuredClone(e.data.state);state.features=(state.features||[]).filter(f=>f.id!==e.data.feature.id);state.features.push(structuredClone(e.data.feature));render();});

// 編集画面専用プレビュー。下書きはメモリ内だけに適用し、ストレージへ書き込まない。
if(isBannerPreview){
 document.addEventListener('click',e=>{if(e.target.closest('.banner-controls'))return;e.preventDefault();e.stopImmediatePropagation();},true);
 document.addEventListener('submit',e=>{e.preventDefault();e.stopImmediatePropagation();},true);
 window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==(window.opener||window.parent)||e.data?.type!=='banner-preview')return;
  state=structuredClone(e.data.state);const slot={...e.data.slot,enabled:true,start:state.date,end:state.date,segment:'all',priority:100};
  const placement=e.data.placement;slot.placements=[placement];state.slots=state.slots.filter(x=>x.id!==slot.id).map(x=>({...x,placements:x.placements.filter(p=>p!==placement)}));state.slots.unshift(slot);
  if(modal.open)modal.close();render();if(placement==='popup')showPopup(bannersAt(state,'popup')[0],{markSeen:false});else if(placement==='interstitial')showInterstitial(bannersAt(state,'interstitial')[0]);
  const target=[...document.querySelectorAll('[data-slot]')].find(el=>el.dataset.slot===slot.id);if(target){target.scrollIntoView({block:'center'});}
 });
}

bindReceipt(render);

bindOptions(refreshCurrentPage);

if(!state.receiptBannerSeeded){state.receiptBannerSeeded=true;state.slots.push({id:'receipt-cheese-banner',name:'クリームチーズ・レシート特集',title:'朝のひとくちを、もっと豊かに。',text:'まろやかクリームチーズ',enabled:true,kind:'banner',placements:['category'],tab:'receipt',position:'top',start:'2026-09-01',end:'2026-12-31',to:'receipt/cheese',destination:null,segment:'all',priority:0});save();render();}

if(!state.sidePopSeeded){const source=state.slots.find(x=>x.enabled&&x.placements?.includes('top'));if(source){for(const tab of ['sidehome','sideoffers'])state.slots.push({...JSON.parse(JSON.stringify(source)),id:'side-pop-'+tab,name:'サイドPOP・'+(tab==='sidehome'?'ホーム':'お得'),placements:['category'],tab,position:'top'});}state.sidePopSeeded=true;save();render();}

if(!state.walkSquareSeeded){if(!state.slots.some(x=>x.tab==='steps'&&x.position==='bottom'))state.slots.push({"id": "walk-square", "name": "歩く・下部サンプル", "title": "秋の休日、旅に出よう。", "enabled": true, "start": "2026-09-01", "end": "2027-12-31", "placements": ["category"], "tab": "steps", "position": "bottom", "to": "offer/travel", "destination": "travel", "kind": "banner", "bannerImage": "data:image/png;base64,"});state.walkSquareSeeded=true;save();render();}

// Restore only after all startup seed/render passes have completed.
if(navigation.view)restorePagePosition(navigation.view);
if(route()[0]==='points'&&route()[1]==='goal')requestAnimationFrame(()=>focusReportGoal(root));
